$('#start').addEventListener('click',startGame);$('#again').addEventListener('click',()=>location.reload());
window.addEventListener('keydown',e=>{key[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!playing)return;if(e.code==='Space')jump();if(e.code==='ShiftLeft'||e.code==='ShiftRight')roll();if(e.code==='KeyE')interact()});window.addEventListener('keyup',e=>key[e.code]=false);
renderer.domElement.addEventListener('click',()=>{if(playing)strike()});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement){cameraYaw-=e.movementX*.0025}else if(mouseDrag){cameraYaw-=(e.clientX-lastMouseX)*.006;lastMouseX=e.clientX}});renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;mouseDrag=true;lastMouseX=e.clientX});window.addEventListener('pointerup',()=>mouseDrag=false);renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());
let jumpVelocity=0,onGround=true;
function jump(){if(onGround&&vigor>8){jumpVelocity=7.8;onGround=false;vigor=Math.max(0,vigor-8)}}
function roll(){if(rollTimer<=0&&vigor>=20){rollTimer=.48;invuln=.65;vigor-=20;toast('Quick step')}}
function strike(){if(attackTimer>0||vigor<5)return;attackTimer=.45;vigor=Math.max(0,vigor-5);let hit=false;for(const e of enemies){if(!e.alive)continue;const d=e.group.position.distanceTo(hero.position);const ahead=new THREE.Vector3(Math.sin(hero.rotation.y),0,Math.cos(hero.rotation.y));const to=e.group.position.clone().sub(hero.position).normalize();if(d<3.1&&ahead.dot(to)>.15){e.hp--;e.group.position.addScaledVector(to,1.3);e.group.scale.set(.84,1.2,.84);setTimeout(()=>e.group.scale.set(1,1,1),130);if(e.hp<=0){e.alive=false;scene.remove(e.group);toast('The forest is quiet again')}else toast('A clean strike');hit=true}}if(!hit)toast('Your blade cuts the air')}
